/* LET'S SCORE: self-contained course artwork; no separate image uploads required. */
const COURSE_ARTWORK = {"science":"data:image/jpeg;base64,","physicsXI":"data:image/jpeg;base64,","physicsXII":"data:image/jpeg;base64,"};
import { initializeApp } from 'https://www.gstatic.com/firebasejs/12.1.0/firebase-app.js';
import { getAuth, createUserWithEmailAndPassword, signInWithEmailAndPassword, onAuthStateChanged, signOut } from 'https://www.gstatic.com/firebasejs/12.1.0/firebase-auth.js';
import { getDatabase, ref, get, set } from 'https://www.gstatic.com/firebasejs/12.1.0/firebase-database.js';

const firebaseConfig={apiKey:'AIzaSyBdsypDM6A2Q1LO3GTueeg8RfTirXGZIP8',authDomain:'lets-score-revisionary-test.firebaseapp.com',databaseURL:'https://lets-score-revisionary-test-default-rtdb.firebaseio.com',projectId:'lets-score-revisionary-test',storageBucket:'lets-score-revisionary-test.firebasestorage.app',messagingSenderId:'629595293837',appId:'1:629595293837:web:b0fd9e83f22651cd577ac4'};
const app=initializeApp(firebaseConfig),auth=getAuth(app),db=getDatabase(app);const $=id=>document.getElementById(id);const params=new URLSearchParams(location.search);
export const courses={
'class10-assamese-free':{name:'Class X Science — Assamese Medium (Free Notes)',className:'Class X',subject:'Science',language:'Assamese',type:'free',description:'Free chapter-wise Class X Science notes in Assamese medium.'},
'class10-assamese-paid':{name:'Class X Science — Assamese Medium',className:'Class X',subject:'Science',language:'Assamese',type:'paid',description:'Chapter-wise notes, NCERT solutions, question bank and practice papers.'},
'class10-english':{name:'Class X Science — English Medium',className:'Class X',subject:'Science',language:'English',type:'paid',description:'Chapter-wise notes, NCERT solutions, question bank and practice papers.'},
'class11-physics':{name:'Class XI Physics — English Medium',className:'Class XI',subject:'Physics',language:'English',type:'paid',description:'Chapter-wise Physics notes, NCERT solutions, question bank and practice papers.'},
'class12-physics':{name:'Class XII Physics — English Medium',className:'Class XII',subject:'Physics',language:'English',type:'paid',description:'Chapter-wise Physics notes, NCERT solutions, question bank and practice papers.'}};
export const message=(id,s)=>{if($(id))$(id).textContent=s};export const currentUserPromise=new Promise(resolve=>onAuthStateChanged(auth,resolve));
export function nav(){const el=$('navLinks');if(!el)return;el.innerHTML=`<a href="index.html">Home</a><a href="courses.html">Courses</a><a href="dashboard.html">My learning</a><a href="revisionary-test.html">Revisionary tests</a><a class="nav-cta" href="register.html">Student login</a>`}
export function courseCards(target='courseGrid'){const el=$(target);if(!el)return;el.innerHTML=Object.entries(courses).map(([id,c])=>{const image=c.subject==='Physics'?(c.className==='Class XI'?COURSE_ARTWORK.physicsXI:COURSE_ARTWORK.physicsXII):COURSE_ARTWORK.science;return `<article class="course-card"><img class="course-artwork" src="${image}" alt="${c.className} ${c.subject} course illustration" loading="eager"><div class="course-card-content"><div class="course-icon">${c.subject==='Physics'?'⚛':'🔬'}</div><div class="eyebrow">${c.className} · ${c.language}</div><h3>${c.name}</h3><p>${c.description}</p><div class="price-line">${c.type==='free'?'Free notes':'₹299 materials <span>·</span> ₹999 with videos'}</div><a class="btn ${c.type==='free'?'btn-light':''}" href="enrolment.html?course=${id}">${c.type==='free'?'Open free course':'View packages'}</a></div></article>`}).join('')}
export async function requireUser(){const u=await currentUserPromise;if(!u){location.href='register.html?next='+encodeURIComponent(location.pathname.split('/').pop()+location.search);return null}return u}
export async function checkAccess(courseId,uid){const c=courses[courseId];if(c?.type==='free'){const selected=await get(ref(db,`studentSelections/${uid}/${courseId}`));return selected.exists()?{active:true,package:'notes',free:true}:null;}const [as,rs]=await Promise.all([get(ref(db,`courseAccess/${courseId}/${uid}`)),get(ref(db,`accessRequests/${courseId}/${uid}`))]);const a=as.val(),r=rs.val();if(!a||a.active!==true)return null;return {...a,package:a.package||r?.package||(r?.includesRecordedVideos?'videos':'notes'),request:r||null};}
export async function resources(courseId,level){const box=$('resourceList');if(!box)return;box.innerHTML='';const cats=['notes','solutions','questions','papers'];if(level==='videos')cats.push('videos');const labels={notes:'Chapter-wise notes',solutions:'NCERT solutions',questions:'Question & answer bank',papers:'Practice / model papers',videos:'Recorded video lectures'};for(const cat of cats){const snap=await get(ref(db,`courseResources/${courseId}/${cat}`));const data=snap.val()||{};const entries=Object.entries(data).filter(([key,x])=>x&&x.url&&!(cat==='videos'&&level!=='videos')).sort((a,b)=>(Number(a[1].sortOrder||a[1].addedAt||0)-Number(b[1].sortOrder||b[1].addedAt||0)));if(!entries.length)continue;const section=document.createElement('section');section.className='resource-section';section.innerHTML=`<h2>${labels[cat]||cat}</h2>`;for(const [key,item] of entries){const a=document.createElement('a');a.className='resource-link';a.href=`resource.html?course=${encodeURIComponent(courseId)}&category=${encodeURIComponent(cat)}&id=${encodeURIComponent(key)}`;a.textContent=(cat==='videos'?'▶ ':'📄 ')+(item.title||'Open resource');section.append(a)}box.append(section)}if(!box.children.length)box.innerHTML='<div class="empty"><strong>No materials published yet</strong><p>Your teacher will add resources here when they are ready.</p></div>';if(level!=='videos'&&courses[courseId]?.type!=='free'){const n=document.createElement('p');n.className='notice';n.textContent='Your access includes study materials. Recorded video lectures are available only with the approved ₹999 package.';box.append(n)}}

if(location.pathname.endsWith('student.html')){
 const login=$('loginBtn'),reg=$('registerBtn'),logout=$('logoutBtn'),name=$('studentName');
 if(login)login.onclick=async()=>{try{await signInWithEmailAndPassword(auth,$('email').value.trim().toLowerCase(),$('password').value);message('authMsg','Login successful. Opening your dashboard…');location.href=params.get('next')||'dashboard.html'}catch(e){message('authMsg',e.code==='auth/invalid-credential'?'Email or password is incorrect.':'Login failed: '+e.message)}};
 if(reg)reg.onclick=async()=>{const email=$('email').value.trim().toLowerCase(),pw=$('password').value,n=name.value.trim();if(!n||pw.length<6||!email){message('authMsg','Enter your name, email and a password of at least 6 characters.');return}try{const cred=await createUserWithEmailAndPassword(auth,email,pw);await set(ref(db,'studentProfiles/'+cred.user.uid),{name:n,email,createdAt:Date.now()});message('authMsg','Account created. Opening your dashboard…');location.href='dashboard.html'}catch(e){message('authMsg',e.code==='auth/email-already-in-use'?'This email already has an account. Please log in.':e.message)}};
 if(logout)logout.onclick=async()=>{await signOut(auth);location.href='index.html'};
 onAuthStateChanged(auth,u=>{if(u){if($('authStatus'))$('authStatus').textContent=`Signed in as ${u.email}`;if(logout)logout.classList.remove('hidden')}})
}
if(location.pathname.endsWith('courses.html'))courseCards();
if(location.pathname.endsWith('enrolment.html')){
 const id=params.get('course')||'class10-english',c=courses[id];if($('selectedCourse'))$('selectedCourse').textContent=c?c.name:'Course not found';if($('package'))$('package').onchange=updateFee;function updateFee(){const video=$('package').value==='videos';$('fee').textContent=`₹${video?999:299}`;$('packageSummary').textContent=video?'Study materials + recorded video lectures':'Study materials only; no recorded video lectures';$('whatsLink').href='https://wa.me/917002137940?text='+encodeURIComponent(`Hello LET'S SCORE. Course: ${c?.name||id}. Package: ${video?'₹999 with videos':'₹299 study materials'}. UTR: ${$('utr')?.value||''}`)}updateFee();
 $('submitRequest')?.addEventListener('click',async()=>{const u=await currentUserPromise;if(!u){message('requestMsg','Please log in first.');return}const utr=$('utr').value.trim().toUpperCase().replace(/[^A-Z0-9]/g,'');if(!utr){message('requestMsg','Enter your UTR after completing the payment.');return}try{const pkg=$('package').value,now=Date.now();await Promise.all([
 set(ref(db,`accessRequests/${id}/${u.uid}`),{utr,courseId:id,package:pkg,fee:pkg==='videos'?999:299,includesRecordedVideos:pkg==='videos',status:'pending',studentUid:u.uid,studentEmail:u.email||'',requestedAt:now}),
 set(ref(db,`studentSelections/${u.uid}/${id}`),{courseId:id,type:'paid',selectedAt:now})
]);message('requestMsg','Request submitted. Your course will unlock after the teacher verifies your payment.');}catch(e){message('requestMsg','Could not submit request: '+e.message)}})
}
if(location.pathname.endsWith('dashboard.html')){
 const u=await requireUser();
 if(u){
  if($('welcome'))$('welcome').textContent=`Welcome back${u.displayName?' '+u.displayName:''}`;
  const el=$('enrolments'); el.innerHTML='';
  try{
   const selectionSnap=await get(ref(db,`studentSelections/${u.uid}`));
   const selected=selectionSnap.val()||{};
   // Read each known course request separately: Firebase rules grant students access
   // to their own request records, not to the entire accessRequests parent node.
   const requestPairs=await Promise.all(Object.keys(courses).map(async courseId=>[
    courseId,(await get(ref(db,`accessRequests/${courseId}/${u.uid}`))).val()
   ]));
   const requestsByCourse=Object.fromEntries(requestPairs);
   // Build the dashboard from both selections and payment requests. Older submissions
   // may have a request record but no studentSelections record; do not hide those.
   const ids=new Set(Object.keys(selected).filter(id=>selected[id]));
   for(const [courseId,request] of Object.entries(requestsByCourse)) if(request) ids.add(courseId);
   const rows=[];
   for(const id of ids){
    const c=courses[id]; if(!c) continue;
    const selection=selected[id];
    if(c.type==='free') { if(selection) rows.push({id,c,free:true}); continue; }
    const [access,request]=await Promise.all([get(ref(db,`courseAccess/${id}/${u.uid}`)),get(ref(db,`accessRequests/${id}/${u.uid}`))]);
    rows.push({id,c,a:access.val(),r:request.val()||requestsByCourse[id],selection});
   }
   const accessible=rows.filter(x=>x.free||x.a?.active===true);
   const showRows=accessible.length?accessible:rows;
   if(accessible.length){const explore=document.querySelector('.section-head a[href="courses.html"]');if(explore)explore.remove();const subtitle=document.querySelector('.section-head p');if(subtitle)subtitle.textContent='Only courses you can currently access are shown here.';}
   for(const item of showRows){const {id,c,a,r,free}=item;
    if(free){el.insertAdjacentHTML('beforeend',`<article class="dash-course"><div><span class="status free">FREE COURSE</span><h3>${c.name}</h3><p>Your selected free course.</p></div><a class="btn" href="learn.html?course=${encodeURIComponent(id)}">Open course</a></article>`);continue;}
    if(a?.active===true){el.insertAdjacentHTML('beforeend',`<article class="dash-course"><div><span class="status success">APPROVED · ${a.package==='videos'?'₹999 VIDEO PACKAGE':'₹299 MATERIALS'}</span><h3>${c.name}</h3><p>Approved course. Open a material to study on its own page.</p></div><a class="btn" href="learn.html?course=${encodeURIComponent(id)}">Continue learning</a></article>`);}
    else {const status=String(r?.status||'not submitted').toUpperCase();el.insertAdjacentHTML('beforeend',`<article class="dash-course"><div><span class="status pending">${r?'PAYMENT '+status:'ENROLMENT NOT COMPLETED'}</span><h3>${c.name}</h3><p>${r?'Your payment request is not yet approved. Course materials remain locked.':'Complete payment and submit your UTR for admin approval.'}</p></div><a class="btn btn-light" href="enrolment.html?course=${encodeURIComponent(id)}">${r?'View payment status':'Complete enrolment'}</a></article>`);}
   }
   if(!el.children.length)el.innerHTML='<div class="empty"><strong>No selected courses yet.</strong><p>Choose a course to begin. Only your selected course and approved enrolments will appear here.</p><a class="btn" href="courses.html">Choose a course</a></div>';
  }catch(e){console.error(e);el.innerHTML='<div class="empty">Could not load your selected courses. Please refresh or sign in again.</div>';}
  $('signout')?.addEventListener('click',async()=>{await signOut(auth);location.href='index.html'});
 }
}
if(location.pathname.endsWith('learn.html')){
 const u=await requireUser();if(u){const id=params.get('course')||'class10-assamese-free',c=courses[id];if(!c){message('learnMsg','Course not found.');}else{$('learnTitle').textContent=c.name;$('learnDescription').textContent=c.description;try{const a=await checkAccess(id,u.uid);if(!a){$('lockedPanel').classList.remove('hidden');$('resourcePanel').classList.add('hidden');const req=(await get(ref(db,`accessRequests/${id}/${u.uid}`))).val();message('lockMsg',req?`Payment request: ${req.status||'pending'}. Access will be available after approval.`:'This course is locked. Please choose a package and submit payment for approval.');$('enrolLink').href=`enrolment.html?course=${id}`}else{ $('lockedPanel').classList.add('hidden');$('resourcePanel').classList.remove('hidden');await resources(id,a.package==='videos'?'videos':'notes')}}catch(e){message('learnMsg','Could not verify course access. Please try again or contact support.')}}}
}
